script:
$output = cmdkey /list | Out-String
Write-Output $output
$targets = @()
foreach ($line in ($output -split '(`r`n|`n)')) {
  if ($line -match '^(目标|Target)\s*:\s*(.+)$') { $targets += $matches[2].Trim() }
}
foreach ($target in $targets) { cmdkey ('/delete:' + $target) | Out-Null }
Write-Output ('已删除 ' + $targets.Count + ' 条缓存的网络凭据。')
exit 0

$name = {{AccountName}}
$done = $false
try { Unlock-LocalUser -Name $name -ErrorAction Stop; $done = $true } catch { }
if (-not $done) {
  $user = [ADSI]('WinNT://' + $env:COMPUTERNAME + '/' + $name + ',user')
  $user.IsAccountLocked = $false
  $user.SetInfo()
}
Write-Output ('已清除账号锁定：' + $name)

$name = {{AccountName}}
net user $name /active:yes | Out-Null
if ($LASTEXITCODE -ne 0) { Write-Error ('启用账号失败，退出码 ' + $LASTEXITCODE); exit $LASTEXITCODE }
Write-Output ('已启用账号：' + $name)

$name = {{AccountName}}
net user $name /active:no | Out-Null
if ($LASTEXITCODE -ne 0) { Write-Error ('停用账号失败，退出码 ' + $LASTEXITCODE); exit $LASTEXITCODE }
Write-Output ('已停用账号：' + $name)

$old = {{AccountName}}
$new = {{NewName}}
$done = $false
try { Rename-LocalUser -Name $old -NewName $new -ErrorAction Stop; $done = $true } catch { }
if (-not $done) {
  $account = Get-CimInstance -ClassName Win32_UserAccount -Filter ("Name='" + $old + "' AND LocalAccount=True")
  if (-not $account) { Write-Error ('未找到本地账号：' + $old); exit 2 }
  Invoke-CimMethod -InputObject $account -MethodName Rename -Arguments @{ Name = $new } | Out-Null
}
Write-Output ('已重命名账号：' + $old + ' → ' + $new)
